# Toutes les boucles en Delphi

## 1. Boucle `FOR...TO` (croissante)

```delphi
var
  i: Integer;
begin
  for i := 1 to 10 do
  begin
    WriteLn('Itération : ', i);  // 1, 2, 3, ..., 10
  end;
end;
```

---

## 2. Boucle `FOR...DOWNTO` (décroissante)

```delphi
var
  i: Integer;
begin
  for i := 10 downto 1 do
  begin
    WriteLn('Itération : ', i);  // 10, 9, 8, ..., 1
  end;
end;
```

---

## 3. Boucle `FOR...IN` (itération sur collection)

### Sur un tableau

```delphi
var
  Nombres: array of Integer;
  Nombre: Integer;
begin
  Nombres := [10, 20, 30, 40, 50];
  for Nombre in Nombres do
  begin
    WriteLn('Valeur : ', Nombre);
  end;
end;
```

### Sur une chaîne de caractères

```delphi
var
  Texte: string;
  C: Char;
begin
  Texte := 'Bonjour';
  for C in Texte do
  begin
    WriteLn('Caractère : ', C);  // B, o, n, j, o, u, r
  end;
end;
```

### Sur un ensemble (set)

```delphi
type
  TJour = (Lundi, Mardi, Mercredi, Jeudi, Vendredi, Samedi, Dimanche);
  TJours = set of TJour;
var
  Weekend: TJours;
  Jour: TJour;
begin
  Weekend := [Samedi, Dimanche];
  for Jour in Weekend do
  begin
    WriteLn('Jour de weekend');
  end;
end;
```

### Sur une TList<T> (générique)

```delphi
uses
  System.Generics.Collections;
var
  Liste: TList<string>;
  Item: string;
begin
  Liste := TList<string>.Create;
  try
    Liste.Add('Alpha');
    Liste.Add('Beta');
    Liste.Add('Gamma');

    for Item in Liste do
    begin
      WriteLn('Élément : ', Item);
    end;
  finally
    Liste.Free;
  end;
end;
```

### Sur un TDictionary<K,V>

```delphi
uses
  System.Generics.Collections;
var
  Dico: TDictionary<string, Integer>;
  Paire: TPair<string, Integer>;
  Cle: string;
begin
  Dico := TDictionary<string, Integer>.Create;
  try
    Dico.Add('Alice', 25);
    Dico.Add('Bob', 30);

    // Itérer sur les paires clé/valeur
    for Paire in Dico do
      WriteLn(Paire.Key, ' => ', Paire.Value);

    // Itérer uniquement sur les clés
    for Cle in Dico.Keys do
      WriteLn('Clé : ', Cle);

  finally
    Dico.Free;
  end;
end;
```

---

## 4. Boucle `WHILE...DO` (tant que)

> ⚠️ Condition testée **avant** chaque itération.

```delphi
var
  i: Integer;
begin
  i := 1;
  while i <= 10 do
  begin
    WriteLn('Itération : ', i);
    Inc(i);  // i := i + 1
  end;
end;
```

---

## 5. Boucle `REPEAT...UNTIL` (répéter jusqu'à)

> ⚠️ Condition testée **après** chaque itération (s'exécute au moins **1 fois**).

```delphi
var
  i: Integer;
begin
  i := 1;
  repeat
    WriteLn('Itération : ', i);
    Inc(i);
  until i > 10;  // On sort quand la condition est VRAIE
end;
```

---

## 6. Boucle infinie (avec sortie manuelle)

### Avec `while True`

```delphi
var
  Saisie: string;
begin
  while True do
  begin
    Write('Entrez "quit" pour sortir : ');
    ReadLn(Saisie);
    if Saisie = 'quit' then
      Break;  // Sort de la boucle
    WriteLn('Vous avez saisi : ', Saisie);
  end;
end;
```

### Avec `repeat...until False`

```delphi
begin
  repeat
    WriteLn('Boucle infinie...');
    // Break pour sortir si besoin
  until False;
end;
```

---

## 7. Contrôle de flux dans les boucles

### `Break` — Sortir de la boucle

```delphi
var
  i: Integer;
begin
  for i := 1 to 100 do
  begin
    if i = 5 then
      Break;  // Sort immédiatement de la boucle
    WriteLn(i);  // Affiche 1, 2, 3, 4
  end;
end;
```

### `Continue` — Passer à l'itération suivante

```delphi
var
  i: Integer;
begin
  for i := 1 to 10 do
  begin
    if i mod 2 = 0 then
      Continue;  // Saute les nombres pairs
    WriteLn(i);  // Affiche 1, 3, 5, 7, 9
  end;
end;
```

### `Exit` — Sortir de la procédure/fonction entière

```delphi
procedure Chercher;
var
  i: Integer;
begin
  for i := 1 to 100 do
  begin
    if i = 42 then
    begin
      WriteLn('Trouvé !');
      Exit;  // Quitte la procédure complètement
    end;
  end;
end;
```

---

## 📊 Tableau récapitulatif

| Type de boucle | Test condition | Cas d'usage |
|---|---|---|
| `for...to` | — (compteur auto) | Nombre d'itérations **connu** (croissant) |
| `for...downto` | — (compteur auto) | Nombre d'itérations **connu** (décroissant) |
| `for...in` | — (itérateur) | Parcourir une **collection/tableau/string** |
| `while...do` | **Avant** chaque tour | Peut ne **jamais** s'exécuter |
| `repeat...until` | **Après** chaque tour | S'exécute **au moins 1 fois** |

> 💡 **Note importante** : En Delphi, le `for` n'autorise qu'un pas de **1** (ou **-1** avec `downto`). Pour un pas personnalisé, utilisez `while` ou `repeat`.

```delphi
// Exemple : compter de 2 en 2
var
  i: Integer;
begin
  i := 0;
  while i <= 20 do
  begin
    WriteLn(i);  // 0, 2, 4, 6, ..., 20
    Inc(i, 2);   // Pas de 2
  end;
end;
```

